// The demo runs. Generated by scripts/demos.ts; the slug is the URL: /demo/<slug>.

import billing from "@/data/traces/billing-agent.json";
import coding from "@/data/traces/coding-agent.json";
import research from "@/data/traces/research-agent.json";
import type { Trace } from "./types";

export const DEMOS = [billing, coding, research] as unknown as Trace[];

export const demoBySlug = (slug: string) => DEMOS.find((d) => d.id === slug);

/** What the run menu and the landing page need to list a demo. */
export type DemoMeta = { slug: string; title: string; description?: string };

export const demoMeta = (): DemoMeta[] => DEMOS.map((d) => ({ slug: d.id, title: d.title, description: d.description }));
